/*! htmx.org v2.0.4 - offline implementation for Cortex.
    Covers: hx-get, hx-post, hx-patch, hx-delete, hx-trigger (click, revealed, keyup, change, submit),
    hx-target, hx-swap, hx-include, hx-confirm, hx-headers, hx-on::before-request, hx-on::after-request,
    htmx-indicator, htmx-request classes, form serialization with JSON body support.
    Replace with production htmx.min.js when network is available:
    curl -sL https://unpkg.com/htmx.org@2.0.4/dist/htmx.min.js -o src/cortex/static/js/htmx.min.js
*/
(function(){
  'use strict';
  var htmx = {
    version: '2.0.4-cortex',
    onLoad: function(cb) {
      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() { cb(document.body); });
      } else {
        cb(document.body);
      }
    },
    process: function(el) { init(el); },
    trigger: function(el, evt) {
      el.dispatchEvent(new Event(evt, {bubbles: true}));
    },
    ajax: function(method, url, opts) {
      var o = opts || {};
      return fetch(url, {method: method, headers: o.headers || {}, body: o.body || null})
        .then(function(r) { return r.text(); })
        .then(function(html) {
          if (o.target) {
            var t = typeof o.target === 'string' ? document.querySelector(o.target) : o.target;
            if (t) doSwap(t, html, o.swap || 'innerHTML');
          }
        });
    },
    _: {}
  };

  function attr(el, name) { return el.getAttribute(name); }
  function hasAttr(el, name) { return el.hasAttribute(name); }
  function findAll(root, sel) { return Array.from((root || document.body).querySelectorAll('[' + sel + ']')); }

  function resolveTarget(el, val) {
    if (!val || val === 'this') return el;
    if (val.startsWith('closest ')) return el.closest(val.slice(8)) || el;
    if (val.startsWith('next ')) return el.nextElementSibling;
    if (val.startsWith('previous ')) return el.previousElementSibling;
    return document.querySelector(val);
  }

  function doSwap(target, html, mode) {
    switch (mode) {
      case 'afterend': target.insertAdjacentHTML('afterend', html); break;
      case 'afterbegin': target.insertAdjacentHTML('afterbegin', html); break;
      case 'beforebegin': target.insertAdjacentHTML('beforebegin', html); break;
      case 'beforeend': target.insertAdjacentHTML('beforeend', html); break;
      case 'outerHTML': target.outerHTML = html; return;
      case 'none': return;
      case 'delete': target.remove(); return;
      default: target.innerHTML = html;
    }
    // Re-initialize any new HTMX elements
    var parent = target.parentElement || document.body;
    init(parent);
  }

  function getMethod(el) {
    if (hasAttr(el, 'hx-get')) return 'GET';
    if (hasAttr(el, 'hx-post')) return 'POST';
    if (hasAttr(el, 'hx-patch')) return 'PATCH';
    if (hasAttr(el, 'hx-put')) return 'PUT';
    if (hasAttr(el, 'hx-delete')) return 'DELETE';
    return null;
  }

  function getUrl(el, method) {
    return attr(el, 'hx-' + method.toLowerCase());
  }

  function collectFormData(el) {
    var form = el.closest('form') || el;
    var fd = new FormData();
    if (form.tagName === 'FORM') {
      fd = new FormData(form);
    }
    // hx-include
    var inc = attr(el, 'hx-include');
    if (inc) {
      var incEls = document.querySelectorAll(inc);
      incEls.forEach(function(ie) {
        if (ie.name && ie.value !== undefined) fd.set(ie.name, ie.value);
      });
    }
    // If the triggering element has a name/value (e.g. input)
    if (el.name && el.value !== undefined && !fd.has(el.name)) {
      fd.set(el.name, el.value);
    }
    return fd;
  }

  function makeRequest(el) {
    var method = getMethod(el);
    if (!method) return;
    var url = getUrl(el, method);
    if (!url) return;

    // hx-confirm
    var confirmMsg = attr(el, 'hx-confirm');
    if (confirmMsg && !confirm(confirmMsg)) return;

    var targetSel = attr(el, 'hx-target');
    var target = resolveTarget(el, targetSel) || el;
    var swap = attr(el, 'hx-swap') || 'innerHTML';

    // Build fetch options
    var fetchOpts = { method: method, headers: {} };

    // Headers from hx-headers
    var headersAttr = attr(el, 'hx-headers');
    if (headersAttr) {
      try { Object.assign(fetchOpts.headers, JSON.parse(headersAttr)); } catch(e) {}
    }

    // Form data for non-GET
    var fd = collectFormData(el);
    if (method === 'GET') {
      var qs = new URLSearchParams(fd).toString();
      if (qs) url += (url.indexOf('?') > -1 ? '&' : '?') + qs;
    } else if (fetchOpts.headers['Content-Type'] === 'application/json') {
      // JSON body — convert FormData to object
      var obj = {};
      fd.forEach(function(v, k) { obj[k] = v; });
      fetchOpts.body = JSON.stringify(obj);
    } else if (method !== 'DELETE') {
      fetchOpts.body = fd;
    }

    // Fire hx-on::before-request
    var brDetail = { requestConfig: fetchOpts, elt: el };
    var brEvt = new CustomEvent('htmx:beforeRequest', { detail: brDetail, bubbles: true, cancelable: true });
    el.dispatchEvent(brEvt);

    // Also check hx-on::before-request attribute
    var onBefore = attr(el, 'hx-on::before-request');
    if (onBefore) {
      try {
        var fn = new Function('event', onBefore);
        var fakeEvt = { detail: brDetail, preventDefault: function() { brEvt._cancelled = true; } };
        fn.call(el, fakeEvt);
      } catch(e) { console.warn('hx-on::before-request error:', e); }
    }

    if (brEvt._cancelled) return;

    // Indicators
    el.classList.add('htmx-request');

    fetch(url, fetchOpts)
      .then(function(r) {
        if (!r.ok && swap === 'none') return '';
        return r.text();
      })
      .then(function(html) {
        el.classList.remove('htmx-request');
        if (swap !== 'none') doSwap(target, html, swap);

        // Fire after-request events
        el.dispatchEvent(new CustomEvent('htmx:afterRequest', { detail: {}, bubbles: true }));

        var onAfter = attr(el, 'hx-on::after-request');
        if (onAfter) {
          try { (new Function(onAfter)).call(el); } catch(e) {}
        }
      })
      .catch(function(err) {
        el.classList.remove('htmx-request');
        console.warn('htmx fetch error:', err);
      });
  }

  function parseTrigger(triggerStr) {
    if (!triggerStr) return { event: 'click', delay: 0, changed: false };
    var parts = triggerStr.split(/\s+/);
    var event = parts[0];
    var delay = 0;
    var changed = false;
    for (var i = 1; i < parts.length; i++) {
      var dm = parts[i].match(/delay:(\d+)ms/);
      if (dm) delay = parseInt(dm[1]);
      if (parts[i] === 'changed') changed = true;
    }
    return { event: event, delay: delay, changed: changed };
  }

  function init(root) {
    if (!root || !root.querySelectorAll) root = document.body;

    // Handle hx-trigger="revealed" (IntersectionObserver)
    if (typeof IntersectionObserver !== 'undefined') {
      findAll(root, 'hx-trigger').forEach(function(el) {
        var trigger = attr(el, 'hx-trigger');
        if (trigger && trigger.trim() === 'revealed' && !el._htmxRevealed) {
          el._htmxRevealed = true;
          var obs = new IntersectionObserver(function(entries) {
            entries.forEach(function(entry) {
              if (entry.isIntersecting) {
                obs.unobserve(el);
                makeRequest(el);
              }
            });
          }, { rootMargin: '200px' });
          obs.observe(el);
        }
      });
    }

    // Handle custom triggers (keyup, change, submit, etc.)
    findAll(root, 'hx-trigger').forEach(function(el) {
      var triggerStr = attr(el, 'hx-trigger');
      if (!triggerStr || triggerStr.trim() === 'revealed' || el._htmxBound) return;
      el._htmxBound = true;

      var parsed = parseTrigger(triggerStr);
      if (parsed.event === 'click') return; // Handled below
      if (parsed.event === 'load') { makeRequest(el); return; }

      var timer;
      var lastVal = el.value;
      el.addEventListener(parsed.event, function() {
        if (parsed.changed && el.value === lastVal) return;
        lastVal = el.value;
        clearTimeout(timer);
        if (parsed.delay > 0) {
          timer = setTimeout(function() { makeRequest(el); }, parsed.delay);
        } else {
          makeRequest(el);
        }
      });
    });

    // Handle click/submit triggers for elements with hx-post, hx-delete, hx-patch, hx-put, hx-get
    var methods = ['hx-post', 'hx-delete', 'hx-patch', 'hx-put', 'hx-get'];
    methods.forEach(function(m) {
      findAll(root, m).forEach(function(el) {
        if (el._htmxClick) return;
        var trigger = attr(el, 'hx-trigger');
        // Skip non-click triggers (handled above)
        if (trigger && trigger !== 'click' && trigger.indexOf('click') === -1) return;
        el._htmxClick = true;

        var eventName = el.tagName === 'FORM' ? 'submit' : 'click';
        el.addEventListener(eventName, function(e) {
          e.preventDefault();
          makeRequest(el);
        });
      });
    });
  }

  // Initialize on DOM ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() { init(document.body); });
  } else {
    init(document.body);
  }

  // Expose globally
  window.htmx = htmx;
})();
